"""Human-facing descriptions for normal Slay the Spire events.

Keys and option indices follow ``Events.h`` and
``GameAction::getValidEventSelectBits`` in sts_lightspeed.  The simulator is
still authoritative about which options are currently legal; this catalog only
adds display text to those legal indices.
"""

from __future__ import annotations


def _event(title_zh, title_en, description_zh, options):
    return {
        "title_zh": title_zh,
        "title_en": title_en,
        "description_zh": description_zh,
        "options": {
            index: {"label_zh": label, "description_zh": description}
            for index, label, description in options
        },
    }


