def describe_event(event_id: str | None, legal_options) -> dict | None:
    """Return JSON-ready text for one event and its currently legal options."""
    if not event_id or event_id == "NEOW":
        return None
    entry = EVENT_DESCRIPTIONS.get(event_id)
    if entry is None:
        entry = _event(
            event_id,
            event_id,
            "当前模拟器没有这项事件的补充描述。",
            [],
        )
    legal_indices = [int(index) for index in (legal_options or [])]
    options = []
    for index in legal_indices:
        text = entry["options"].get(index, {
            "label_zh": f"选项 {index + 1}",
            "description_zh": "当前模拟器没有这项选项的补充描述。",
        })
        if event_id == "Colosseum" and index == 0:
            text = (
                {"label_zh": "逃离", "description_zh": "带着第一场战斗的奖励离开竞技场。"}
                if 1 in legal_indices
                else {"label_zh": "战斗", "description_zh": "进入竞技场的第一场战斗。"}
            )
        options.append({"index": index, **text})
    return {
        key: entry[key]
        for key in ("title_zh", "title_en", "description_zh")
    } | {"event_id": event_id, "options": options}
